const mkey=()=> 'little_lab_crafting_v1_'+suffix();
const legacyKey=()=> 'little_lab_visual_gear_v1_'+suffix();
const tester=()=>false;
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k)||'null')??f}catch{return f}};
function clean(x){const owned=[...new Set((Array.isArray(x.owned)?x.owned:[]).filter(id=>byId[id]))];const eq=Object.fromEntries(Object.entries(x.eq||{}).filter(([s,id])=>byId[id]?.slot===s&&owned.includes(id)));const enhancements=Object.fromEntries(Object.entries(x.enhancements||{}).filter(([id])=>owned.includes(id)&&byId[id]?.rank===5).map(([id,v])=>[id,Math.min(12,Math.max(0,Math.floor(Number(v)||0)))]));return{owned,eq,enhancements,active:ITEMS.some(i=>i.slot===x.active)?x.active:'head'}}
function load(){let g=read(gkey(),null);if(!g){const old=read(legacyKey(),{});const owned=tester()?[]:(old.owned||[]).map(id=>oldMap[id]).filter(Boolean);let eq={};for(const oldId of old.equipped||[]){const id=oldMap[oldId];if(id&&owned.includes(id))eq[byId[id].slot]=id}g=clean({owned,eq,active:'head'});localStorage.setItem(gkey(),JSON.stringify(g))}const raw=read(mkey(),null);const materials=Object.fromEntries(mats.map(m=>[m,Math.max(0,Math.floor(Number(raw?.[m]??(tester()?999:0))||0))]));return {...clean(g),materials}}
function save(s){const g=clean(s);const materials=Object.fromEntries(mats.map(m=>[m,Math.max(0,Math.floor(Number(s.materials?.[m])||0))]));const a=gkey(),b=mkey(),oldA=localStorage.getItem(a),oldB=localStorage.getItem(b);try{localStorage.setItem(a,JSON.stringify(g));localStorage.setItem(b,JSON.stringify(materials))}catch(e){for(const [k,v] of [[a,oldA],[b,oldB]]){try{if(v===null)localStorage.removeItem(k);else localStorage.setItem(k,v)}catch{}}throw e}updateSummary()}
