 if(slot){const b=(slot==='gloves'||slot==='weapon'||slot==='wrist')?(slot==='weapon'&&eq.weapon==='weapon2'?[110,-5,145,230]:eq.weapon?[120,125,230,180]:[140,170,210,165]):slot==='neck'?[185,76,118,95]:slot==='boots'?[172,328,113,162]:slot==='outfit'?[105,80,270,300]:slot==='back'?[30,10,420,470]:[137,-28,210,190];return [b[0],b[1]+28,b[2],b[3]];}
