function jqElfHDHTML(eq,view,context='main'){
 if(jqMythicV8.has(eq))return jqMythicHTML(eq,view,context,5);
 const b=view||[0,0,480,533];const pos=(x,y,w,h)=>`left:${(x-b[0])/b[2]*100}%;top:${(y-b[1])/b[3]*100}%;width:${w/b[2]*100}%!important;height:${h/b[3]*100}%!important;`;
 const max=context==='main'?'width:min(100%, 370px, 53vh);':context==='home'?'width:auto;height:100%;max-width:100%;max-height:100%;flex-shrink:0;':context==='preview'?'width:min(100%, 290px);':'width:100%;';
 let html=`<div class="jq-elf-hd jq-elf-hd-${context}" role="img" aria-label="여요정 HD 장비 착용 모습" style="position:relative;overflow:hidden;aspect-ratio:${b[2]}/${b[3]};${max}margin:0 auto;isolation:isolate;pointer-events:none;">`;
 html+=`<span style="position:absolute;${pos(162,504,156,16)}background:rgba(8,15,27,.45);border-radius:50%"></span>`;
 for(const l of jqElfHDLayers(eq))html+=`<img class="jw-elf-depth" data-jw60-layer="${l.role}" alt="" draggable="false" src="${l.src}" style="--jw60-z:${l.role==='rear'?-2:l.role==='body'?0:1}px;position:absolute!important;${pos(l.x,l.y,l.w,l.h)}max-width:none!important;max-height:none!important;min-width:0!important;min-height:0!important;object-fit:fill!important;display:block!important;margin:0!important;padding:0!important;border:0!important;filter:none!important;box-shadow:none!important;opacity:1!important;border-radius:0!important;">`;
 return html+(Object.values(eq).some(x=>/5$/.test(x))?'<svg viewBox="0 0 480 505" style="position:absolute;inset:0;width:100%;height:100%;pointer-events:none">'+mythicAura(eq)+'</svg>':'')+'</div>';
}
function jqElfHDThumb(id){if(/5$/.test(id))return jqMythicThumb(id);const ref=jqElfHDData.thumbs[id]||jqElfHDData.a.front[id];return ref&&jqElfHDAssets[ref.$asset]?.src;}
function jqElfArt31(eq){if(jqMythicV8.has(eq))return jqMythicFragment(eq,5);return '<g transform="translate(12.61 0) scale(.947467)"><ellipse cx="240" cy="512" rx="78" ry="8" fill="#080f1b" opacity=".45"/>'+jqElfHDLayers(eq).map(l=>`<image href="${l.src}" x="${l.x}" y="${l.y}" width="${l.w}" height="${l.h}" preserveAspectRatio="none"/>`).join('')+'</g>';}
const jqFit32=window.JQOriginalFit32;
const jqMythicV8=window.JQCreateMythicArt(jqElfHDData,jqElfHDAssets,jqFit32,jqHood33);
function jqMythicThumb(id,lv){return jqMythicV8.thumb(id,lv??load().enhancements?.[id]??0)}
function jqMythicHTML(eq,view=null,context='main',idx=mascotIndex){
 const e=load().enhancements||{};
 if(Array.isArray(view)&&view[2]>=479&&view[3]>=532)view=null;
 const src=jqMythicV8.image(idx,eq,e,view);if(!src)return '';
 const w=context==='home'
  ?'max-height:100%;max-width:100%;width:auto;height:auto;'
  :context==='main'
  ?'width:auto!important;height:100%!important;max-width:100%!important;max-height:100%!important;'
  :context==='preview'
  ?'max-height:420px;width:100%;'
  :'width:100%;';
 return `<img class="jq-mythic-v8-art" alt="신화 장비 착용 모습" draggable="false" src="${src}" style="display:block!important;object-fit:contain;${w}margin:0 auto;pointer-events:none;color-scheme:only dark;">`;
}
function jqMythicFragment(eq,idx){const src=jqMythicV8.image(idx,eq,load().enhancements||{});return `<image href="${src}" x="0" y="0" width="480" height="505" preserveAspectRatio="xMidYMid meet"/>`;}
function jqClassArt32(eq,idx=mascotIndex){
 if(jqMythicV8.has(eq)&&idx>=0&&idx<8)return jqMythicFragment(eq,idx);
 const aura=mythicAura(eq);eq=mythicEq(eq);
 if(idx===5)return jqElfArt31(eq)+aura;
 const d=jqFit32,f=d.fits[idx];if(!f)return '';
 const [hx,hy,cx,ny,lx,rx,lf,rf,shoulder,hips]=f,male=idx<4;
 const rank=id=>Number(id?.slice(-1));
 const img=(src,x,y,w,h)=>src?`<image href="${src}" x="${x}" y="${y}" width="${w}" height="${h}" preserveAspectRatio="none"/>`:'';
 const front=(id,x,y,w,h)=>img(d.front[id],x,y,w,h);
 let out='<ellipse cx="240" cy="458" rx="80" ry="8" fill="#080f1b" opacity=".4"/><g transform="translate(23 29) scale(1.4)">';
 if(eq.back)out+=img(d.rear[eq.back],cx-119,ny+2,238,222);
 let weapon='';if(eq.weapon){const r=rank(eq.weapon),g=eq.gloves?.slice(-1),a=d.weapons[g!==undefined?eq.weapon+'g'+g:eq.weapon]||d.weapons[eq.weapon];if(a){const h=[220,196,174,195,201][r],w=h*a.w/a.h;weapon=img(a.src,lx-5-a.gx*w/a.w,163-a.gy*h/a.h,w,h);out+=weapon;}}
 out+=img(male&&eq.outfit?d.male[idx][rank(eq.outfit)]:d.base[idx],0,0,310,326);
 if(eq.outfit){const r=rank(eq.outfit);if(male)out+=front(eq.outfit+'male',cx-shoulder*.51,ny+5,shoulder*1.02,86);else out+=front(eq.outfit,cx-hips*1.6,ny+5,hips*3.2,188);}
 if(eq.boots){for(const [j,fx] of [[0,lf],[1,rf]])out+=front(eq.boots+j,fx-(male?16:12),male?234:241,male?33:26,male?63:56);}
 if(eq.back&&d.front[eq.back])out+=front(eq.back,cx-shoulder*.53,ny-1,shoulder*1.06,31);
 if(eq.neck)out+=front(eq.neck,cx-20,ny-5,40,34);
 if(eq.gloves){for(const [j,x] of [[0,lx],[1,rx]])out+=front(eq.gloves+j,x-10,148,20,29);}
 if(eq.wrist){for(const [j,x] of [[0,lx],[1,rx]])out+=front(eq.wrist+j,x-9,144,18,13);}
 if(eq.weapon)out+=weapon;
 if(eq.head){const r=rank(eq.head);if(r===1){const [xx,w,h,y]=({0:[162,80,86,-10],1:[151,80,86,-10],2:[162,80,86,-10],3:[160,80,86,-8],4:[156,74,88,0],6:[155,74,88,0],7:[149,74,88,2]})[idx];out+=img(jqHood33,xx-w/2,y,w,h);}else{const ww=[44,62,58,76,48][r]+(male?2:0),hh=[12,52,47,36,20][r],yy=[hy-15,hy-43,hy-40,hy-48,hy-24][r];out+=front(eq.head,hx-ww/2,yy,ww,hh);}}
 return out+'</g>'+aura;
}

function enhanceDropRates(){const g=load();const count=Math.min(8,new Set(Object.values(g.eq||{}).filter(id=>g.owned.includes(id)&&byId[id]?.rank===4)).size);return {count,quiz:count/3,chest:count*4/3};}
function rollEnhanceFragment(source){const rates=enhanceDropRates();const rate=source==='quiz'?rates.quiz:source==='chest'?rates.chest:0;return rate>0&&Math.random()*100<rate;}
window.LabGearBridge={load,save,loadCraft,saveCraft,enhanceDropRates,rollEnhanceFragment,isTester:tester,soundKey:()=>bpkey()+'_sound',label:()=>String(player||'')+' · '+String(grade||''),elfArt:jqElfArt31,elfHTML:jqElfHDHTML,mythicThumb:jqMythicThumb,mythicHTML:jqMythicHTML,hasMythic:jqMythicV8.has,elfView:jqElfHDView,elfThumb:jqElfHDThumb,classArt:jqClassArt32,hasFit:()=>mascotIndex>=0&&mascotIndex<8,character:()=>({index:mascotIndex,name:mascotIndex===CUSTOM_PHOTO_INDEX?'내 사진':(MASCOTS[mascotIndex]||MASCOTS[0]).name,src:mascotURL(mascotIndex,player,grade)}),equippedPortrait:(idx,name,level)=>{const suffix=encodeURIComponent(name)+'_'+encodeURIComponent(level);const st=clean(read('little_lab_gear8_v1_'+suffix,{}));return jqMythicV8.has(st.eq)?jqMythicV8.image(idx,st.eq,st.enhancements):'';},openRoom,openWorkshop,openCraft:id=>openWorkshop('workshop',id),openChests:()=>openWorkshop('chests'),openBag:()=>openWorkshop('bag')};
let overlay,frame,craftFrame,frameProfile='',craftProfile='',ready=false,craftReady=false,mode='gear',pendingTab='workshop',pendingItem=null,previousOverflow='',focusBefore=null;
function ensure(){if(overlay)return;overlay=document.createElement('section');overlay.id='labGearOverlay';overlay.hidden=true;overlay.innerHTML='<header><div class="jq-room-title"><img id="jqRoomPortrait" alt=""><div><strong id="labModeTitle">영웅 장비실</strong><small id="jqRoomClass"></small></div></div><button type="button" id="labGearClose">학습 화면 돌아가기</button></header><nav id="labModeNav"><button id="labCraftNav">제작 공방</button><button id="labWearNav">영웅 장비실</button></nav><iframe title="48종 장비 착용" id="labGearFrame"></iframe><iframe title="제작 및 용해 공방" id="labCraftFrame" hidden></iframe>';document.body.append(overlay);frame=overlay.querySelector('iframe');overlay.querySelector('#labGearClose').onclick=closeRoom;craftFrame=overlay.querySelector('#labCraftFrame');overlay.querySelector('#labCraftNav').onclick=()=>openWorkshop('workshop');overlay.querySelector('#labWearNav').onclick=openRoom;craftFrame.addEventListener('load',()=>{try{craftReady=!!craftFrame.contentWindow.labCraftReady;if(craftReady&&mode==='craft')craftFrame.contentWindow.labCraftSync(pendingTab,pendingItem)}catch(e){console.warn(e)}});frame.addEventListener('load',()=>{try{ready=typeof frame.contentWindow.labGearPreview==='function';if(ready)updateSummary(true)}catch{ready=false}})}
function prepare(){if(!player||!grade)return;ensure();const id=suffix()+'|'+String(mascotIndex);if(frameProfile!==id){frameProfile=id;ready=false;frame.srcdoc=ROOM;if(craftProfile!==id){craftProfile='';craftReady=false;craftFrame.removeAttribute('srcdoc')}}}
function openOverlay(next){if(!player||!grade)return false;prepare();if(overlay.hidden){focusBefore=document.activeElement;previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';overlay.hidden=false}mode=next;const hero=window.LabGearBridge.character();overlay.querySelector('#jqRoomPortrait').src=hero.src;overlay.querySelector('#jqRoomClass').textContent=hero.name;frame.hidden=next!=='gear';craftFrame.hidden=next!=='craft';overlay.querySelector('#labModeTitle').textContent=next==='gear'?'영웅 장비실':'마법 제작 공방';overlay.querySelector('#labCraftNav').setAttribute('aria-pressed',String(next==='craft'));overlay.querySelector('#labWearNav').setAttribute('aria-pressed',String(next==='gear'));return true}
function openRoom(){if(!openOverlay('gear'))return;try{if(ready){frame.contentWindow.labGearSync();updateSummary(true)}}catch(e){console.warn(e)}}
function openWorkshop(tab='workshop',id=null){if(!openOverlay('craft'))return;pendingTab=tab;pendingItem=id;loadCraft();const profile=suffix()+'|'+String(mascotIndex);if(craftProfile!==profile){craftProfile=profile;craftReady=false;craftFrame.srcdoc=CRAFT}else if(craftReady)try{craftFrame.contentWindow.labCraftSync(tab,id)}catch(e){console.warn(e)}}
function closeRoom(){if(!overlay)return;overlay.hidden=true;document.body.style.overflow=previousOverflow;try{if(ready)frame.contentWindow.labGearSync();if(craftReady)craftFrame.contentWindow.document.querySelectorAll('dialog[open]').forEach(d=>craftFrame.contentWindow.closeModal(d));}catch(e){console.warn(e)}try{if(typeof menu==='function'&&document.querySelector('.screen .subjects'))menu();else if(typeof dressPage==='function'&&document.querySelector('.screen .costume'))dressPage()}catch(e){console.warn(e)}updateSummary(true);if(focusBefore?.isConnected)focusBefore.focus()}
function updateSummary(withArt=false){if(!player||!grade)return;const panel=document.getElementById('labGearHome');if(!panel)return;const st=load(),hero=window.LabGearBridge.character();panel.querySelector('.lab-gear-count').textContent=hero.name+' · '+Object.keys(st.eq).length+' / 8 착용 · '+st.owned.length+' / 48 보유';panel.querySelector('.jq-preview-toggle')?.remove();delete panel.dataset.jqArt;if(withArt||window.LabGearBridge.hasFit()){try{const host=panel.querySelector('.lab-gear-preview');host.innerHTML=window.LabGearBridge.hasFit()&&jqMythicV8.has(st.eq)?jqMythicHTML(st.eq,null,'home'):mascotIndex===5?jqElfHDHTML(st.eq,null,'home'):window.LabGearBridge.hasFit()?`<svg viewBox="0 0 480 505" role="img" aria-label="장비 착용 모습">${jqClassArt32(st.eq)}</svg>`:mascotImage(mascotIndex,'jq-home-portrait',player,grade);host.setAttribute('aria-label',hero.name+' 착용 모습')}catch(e){console.warn(e)}}}
function installHome(){if(!player||!grade)return;const screen=document.querySelector('.screen');if(!screen)return;const isHome=!!screen.querySelector('.subjects'),isDress=!!screen.querySelector('.costume');if(!isHome&&!isDress)return;if(!screen.querySelector('#labGearHome')){const panel=document.createElement('section');panel.id='labGearHome';panel.innerHTML='<div class="lab-gear-home-head"><div><strong>영웅 장비실</strong><small class="lab-gear-count"></small></div><button type="button" class="primary" id="labGearOpen">착용 · 비교</button></div><div class="lab-gear-shortcuts"><button data-lab-tab="workshop">제작 공방</button><button data-lab-tab="blueprints">도안 공방</button><button data-lab-tab="salvage">용해 공방</button><button data-lab-tab="chests">보물상자</button><button data-lab-tab="enhance">강화 공방</button></div><div class="lab-gear-preview" aria-label="판타지 장비 착용 캐릭터"></div><small class="lab-gear-caption">48종 장비 · 8개 착용 부위</small>';const anchor=isHome?(screen.querySelector('.mascot-row')||screen.firstChild):(screen.querySelector('.card')||screen.firstChild);if(anchor)anchor.after(panel);else screen.prepend(panel);panel.querySelector('#labGearOpen').onclick=openRoom;panel.querySelectorAll('[data-lab-tab]').forEach(b=>b.onclick=()=>openWorkshop(b.dataset.labTab))}loadCraft();prepare();updateSummary(true)}
const oldMenu=menu;menu=function(){const r=oldMenu.apply(this,arguments);installHome();return r};
const oldDress=dressPage;dressPage=function(){const r=oldDress.apply(this,arguments);installHome();return r};
// Route the original home tiles and bag equipment tab to the new equipment room.
window.addEventListener('click',e=>{const el=e.target.closest('[data-panel="craft"],[data-panel="gear"],[data-panel="chest"],#openTreasure,#rewardInventoryPanel [data-tab="equipment"],#goTreasure');if(!el||!player||!grade)return;e.preventDefault();e.stopImmediatePropagation();if(el.id==='goTreasure'){menu();openWorkshop('workshop')}else if(el.dataset.panel==='chest'||el.id==='openTreasure')openWorkshop('chests');else if(el.dataset.panel==='craft')openWorkshop('workshop');else openRoom()},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&overlay&&!overlay.hidden){e.preventDefault();closeRoom()}});
window.addEventListener('load',()=>{if(player&&grade)installHome()});
